INSERT [dbo].[Points] ([PointID], [Title], [Summary], [Description], [CustomerID], [ProductID], [ReportedByID], [AssignedToID], [DateCreated], [StartDate], [DateCompleted], [DateClosed], [Status], [Priority], [Category], [Complexity], [TicketID], [ExpectedDate], [DateSentToQC], [TesterStartDate], [DeveloperRemark], [TesterRemark], [TesterCompleteDate], [SortOrder], [IsVerified], [IsDeadlineNotified], [ExpectedMinutes], [TotalTimeSpent], [PauseTimeMinutes], [LastActionTime], [SupportStartDate], [SupportCompleteDate], [SupportTimeSpent], [SupportPauseTime], [SupportLastActionTime], [IsSupportPaused], [SupportRemark], [IsDeveloperPaused], [VerificationStatus], [ToDoDate], [MergeAssignedToID], [DateSentToMerge], [DateSupportVerified], [DateTicketVerified], [AdminRemark], [Module], [SubModule]) VALUES (5989, N'estimation Spine in case of book', N'Estimation', N'Perfect Binding = Rate/SqureCM(Height*Spine)/Order Quantity      If i go through Book plan  the calculation reflecting is correct. lekin agar mai reload kr ke estimation pe no of pages change krti hun to meri spine change hogi, but estimation me wo update nho hoti hai, 
2nd condition = agar kisi case me maine catagory me perfect binding ka process allocate nhi kiya hai to mujhe mannualy select krna hoga uss time bhi book ka spine calculate nhi hota hai q ki waha pe kshi bhi book spine khi bhi mention nhi hai . iuska calculation humne sirf backend me set kiya hua hai . 
3rd condition - agar  maine book plan se na jaake directly plan kiya to uss case me bhi hum kahi pe mention nhi krte hai ki mera book spine kitna hai ., to uss case me bhi hume book spine ka calculation bithana padhega .', 226, 7, 168, 184, CAST(N'2026-07-06T00:00:00.000' AS DateTime), NULL, NULL, NULL, N'Assigned', N'Medium', N'Improvement', N'Complex', 4026, CAST(N'2026-07-06T04:46:00.000' AS DateTime), NULL, NULL, NULL, NULL, NULL, NULL, 1, 0, 20, NULL, 0, NULL, NULL, NULL, NULL, NULL, NULL, 0, NULL, 0, 1, NULL, NULL, NULL, NULL, CAST(N'2026-07-06T17:15:40.053' AS DateTime), NULL, NULL, NULL)
